import {SKILLS,KEY,fresh,restore,start,submit,advance,mastery,tier} from './engine.mjs?v=20261011-sounds';
import {REGIONS,landscape,fox,owl} from './art.mjs?v=20261011-sounds';
const $=id=>document.getElementById(id);
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lantern=`<svg viewBox="0 0 50 65" aria-hidden="true"><path d="M15 17V10Q25 -2 35 10V17" fill="none" stroke="#4ce4e9" stroke-width="4"/><rect x="9" y="17" width="32" height="39" rx="9" fill="#ed5da6" stroke="#4ce4e9" stroke-width="3"/><path d="M25 25Q13 40 25 46Q37 40 25 25" fill="#ffdf7d"/><path d="M7 58H43M8 17H42" stroke="#4ce4e9" stroke-width="4" stroke-linecap="round"/></svg>`;
const SOUND_KEY='lantern-hollow-sound-v1';
let soundOn=true,audioContext=null;
try{soundOn=localStorage.getItem(SOUND_KEY)!=='off';}catch{}
function saveSound(){try{localStorage.setItem(SOUND_KEY,soundOn?'on':'off');}catch{}}
function audio(){
 if(!soundOn)return null;
 const AudioContext=globalThis.AudioContext||globalThis.webkitAudioContext;
 if(!AudioContext)return null;
 if(!audioContext)audioContext=new AudioContext();
 if(audioContext.state==='suspended')audioContext.resume?.();
 return audioContext;
}
function note(ctx,{f,at=0,d=.12,v=.028,type='square',to=f}){
 const osc=ctx.createOscillator(),gain=ctx.createGain(),startAt=ctx.currentTime+at;
 osc.type=type;osc.frequency.setValueAtTime(f,startAt);if(to!==f)osc.frequency.exponentialRampToValueAtTime(to,startAt+d);
 gain.gain.setValueAtTime(.0001,startAt);gain.gain.exponentialRampToValueAtTime(v,startAt+.012);gain.gain.exponentialRampToValueAtTime(.0001,startAt+d);
 osc.connect(gain);gain.connect(ctx.destination);osc.start(startAt);osc.stop(startAt+d+.025);
}
function playSound(name){
 const ctx=audio();if(!ctx)return;
 const sounds={
  start:[{f:220,at:0},{f:330,at:.09},{f:440,at:.18,d:.18,type:'sawtooth'}],
  correct:[{f:523,at:0},{f:659,at:.065},{f:784,at:.13},{f:1047,at:.2,d:.2}],
  wrong:[{f:220,at:0,d:.18,v:.022,type:'triangle',to:185},{f:165,at:.13,d:.22,v:.018,type:'triangle',to:147}],
  hint:[{f:659,at:0,d:.13,v:.018,type:'sine'},{f:988,at:.08,d:.2,v:.021,type:'sine'}],
  step:[{f:330,at:0,d:.1,v:.018,type:'triangle'},{f:494,at:.07,d:.15,v:.02,type:'triangle'}],
  toggle:[{f:440,at:0,d:.1,v:.018,type:'sine'},{f:660,at:.07,d:.14,v:.02,type:'sine'}],
  finish:[{f:262,at:0,d:.16,type:'sawtooth'},{f:330,at:.09,d:.16,type:'sawtooth'},{f:392,at:.18,d:.16,type:'sawtooth'},{f:523,at:.29,d:.28,v:.034,type:'sawtooth'},{f:659,at:.38,d:.27,v:.028},{f:784,at:.47,d:.32,v:.026}]
 };
 (sounds[name]||[]).forEach(n=>note(ctx,n));
}
let warning='',s;try{const raw=localStorage.getItem(KEY);s=raw?restore(raw):fresh();if(!s){s=fresh();warning='The saved journey could not be read. A fresh trail is ready; the old save is kept until you begin.';}}catch{s=fresh();warning='Saving is unavailable in this browser. You can play, but this journey may not be kept.';}
let screen=s.active?'game':'home',finished=null;
function save(){try{localStorage.setItem(KEY,JSON.stringify(s));warning='';}catch{warning='Your browser could not save progress. Keep this tab open; storage may be full or disabled.';}}
const date=x=>new Date(x).toLocaleDateString(undefined,{month:'short',day:'numeric'});
function render(){
 $('app').innerHTML=`<header><div class="brand">${lantern} Lantern Hollow</div><div class="header-actions"><button type="button" class="sound-toggle" id="soundToggle" aria-pressed="${soundOn}">${soundOn?'♪ Sound on':'Sound off'}</button><button type="button" class="link" id="parentToggle">${screen==='parent'?'Back to the trail':'Parent journal'}</button></div></header>${warning?`<div class="notice" role="status">${esc(warning)}</div>`:''}<main id="main" class="fade-in">${screen==='home'?home():screen==='game'?game():screen==='finish'?finish():parent()}</main><div class="footer">PIP & THE NEON TRAIL  •  TEN LANTERNS  •  ONE ENCORE</div>`;
 $('parentToggle').onclick=()=>{screen=screen==='parent'?(s.active?'game':finished?'finish':'home'):'parent';render();};
 bind();
}
function home(){return `<section class="hero"><div class="eyebrow">PIP & THE NEON TRAIL · ONE NIGHT ONLY</div><h1>LIGHT UP<br>THE NIGHT.</h1><p class="lead">Pip has a guitar. The woods need a spark.<br>Light ten lanterns and bring down the house.</p><button class="primary" id="begin">${s.active?'CONTINUE THE SHOW':'START THE SHOW'} <span aria-hidden="true">→</span></button><p class="subtle" style="margin:15px 0 0">10 lanterns · about 8–10 minutes · no timer</p></section><div class="home-scene">${landscape(0,s.journeys,true)}<span class="scene-label">Journey ${s.journeys+1} · ${REGIONS[s.journeys%6]}</span><span class="scene-note">${s.journeys?`${s.journeys} ${s.journeys===1?'trail':'trails'} illuminated`:'THE SHOW STARTS HERE'}</span></div><div class="home-bottom"><div><span class="number">1</span><div><strong>Find your rhythm</strong>Solve little puzzles along the neon trail.</div></div><div><span class="number">2</span><div><strong>Pip’s got your back</strong>Ask for a hint whenever you need one.</div></div><div><span class="number">3</span><div><strong>End on an encore</strong>Ten lanterns, then the show is over.</div></div></div>`;}
function visual(q){if(!q.visual)return '';const v=q.visual;return `<div class="visual">${v.type==='bar'?`<div class="bar" role="img" aria-label="${esc(v.label)}">${Array.from({length:v.parts},(_,i)=>`<i class="${i<v.filled?'filled':''}"></i>`).join('')}</div><p>${esc(v.label)}</p>`:`<table><thead><tr>${v.headers.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${v.rows.map(row=>`<tr>${row.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table>`}</div>`;}
function game(){
 const run=s.active;if(!run){screen='home';return home();}
 const q=run.question,fb=run.feedback,done=run.results.length,step=fb?done:done+1;
 return `<div class="journey-top"><div><div class="eyebrow">Journey ${s.journeys+1}</div><h2>${REGIONS[s.journeys%6]}</h2></div><div><div class="trail-count">Lantern ${step} of 10</div><button type="button" class="link" id="pause" style="font-size:11px;padding:7px 0">Pause & save</button></div></div><div class="game-scene">${landscape(done,s.journeys)}</div><div class="progress-dots" aria-label="${done} of 10 encounters complete">${Array.from({length:10},(_,i)=>`<span class="${i<done?'lit':i===done?'current':''}"></span>`).join('')}</div><div class="game-layout"><aside class="companion">${q.transfer?owl():fox()}<strong>${q.transfer?'Orin':'Pip'}</strong><span>${q.transfer?'Keeper of the trail':'Your trail companion'}</span></aside><section class="puzzle" aria-labelledby="question"><span class="tag ${q.transfer?'boss':''}">${q.transfer?'Guardian’s riddle':q.repair?'A smaller stepping stone':['A favor for a friend','Along the woodland path','A little lantern puzzle'][q.form]}</span><h2 id="question" tabindex="-1">${esc(q.prompt)}</h2>${visual(q)}<div class="choices">${q.choices.map((c,i)=>`<button type="button" class="choice ${fb?(c===q.answer?'correct':c===fb.chosen?'wrong':''):''}" data-choice="${esc(c)}" ${fb?'disabled':''}><span class="key" aria-hidden="true">${i+1}</span><span>${esc(c)}${fb&&c===q.answer?' ✓':''}</span></button>`).join('')}</div>${!fb?`<div class="help-row"><button type="button" class="link" id="hint">${q.assisted?'Hint is open':'Ask Pip for a hint'}</button><span class="subtle">Paper & pencil welcome</span></div>${q.assisted?`<div class="hint-box" role="status">${esc(q.hint)}</div>`:''}`:`<div class="feedback ${fb.correct?'':'neutral'}" role="status"><strong>${fb.correct?(q.transfer?'GUARDIAN RIFF CLEARED!':'THE CROWD GOES WILD!'):'Let’s look at it together.'}</strong><p>${esc(q.explain)}${!fb.correct?(done===10?' We’ll give this idea another look on a later trail.':' We’ll give this idea another look with a little help.'):''}</p><button type="button" class="primary" id="next">${done===10?'Head home to camp':'On we go'} <span aria-hidden="true">→</span></button></div>`}</section></div>`;
}
function finish(){return `<section class="completion"><div class="keepsake">${lantern}</div><div class="eyebrow">Journey ${s.journeys} complete</div><h1>ENCORE!<br>THE NIGHT IS YOURS.</h1><p>Ten lanterns lit. Pip made it home.<br>You kept the music going. That’s a wrap for today.</p><div class="home-scene">${landscape(10,Math.max(0,s.journeys-1))}</div><div class="finish-stats"><div><strong>10</strong><span>lanterns lit</span></div><div><strong>${s.journeys}</strong><span>${s.journeys===1?'journey':'journeys'} completed</span></div></div><button class="primary" id="done">END THE SHOW ✓</button><p class="subtle" style="margin-top:22px">Your next adventure will be waiting right here.</p></section>`;}
function parent(){const errors=s.history.filter(x=>!x.correct).slice(-12).reverse(),sessions=s.sessions.slice(-10);return `<section class="parent"><div class="eyebrow">For the grown-ups</div><h1 style="font-size:43px">The field journal</h1><p class="parent-intro">${s.total} encounters · ${s.journeys} completed journeys. Progress is saved in this browser on this device. Hints and guided retries are recorded separately from independent success.</p><div class="skill-grid">${Object.entries(SKILLS).map(([k,label])=>{const t=s.skills[k];return `<article class="skill-card"><div class="row"><h3>${label}</h3><strong>${t.attempts?Math.round(t.score*100)+'%':'—'}</strong></div><small>${mastery(t)} · ${t.attempts} attempts</small><div class="meter"><i style="width:${t.attempts?t.score*100:0}%"></i></div><small>Difficulty ${tier(t)} / 4 · ${t.transfer} independent transfer ${t.transfer===1?'success':'successes'}</small></article>`;}).join('')}</div><details><summary>How to read these estimates</summary><p>These are practice estimates, not test scores or diagnoses. Every skill begins with the same low-confidence prior (18%), regardless of the report. Independent success gradually raises the estimate; an incorrect answer lowers it. Hinted answers and immediate guided retries do not raise mastery. “Growing strong” additionally requires two independent transfer successes and more than one representation.</p><p>Question selection balances skills that need work, skills not yet explored, and time since last practice. Errors receive an easier next step and a later transfer retry. Each journey ends at ten encounters, even if a review is still due; that review carries over. Encounter five and ten normally feature the guardian, but needed support takes priority.</p><p>The report informed the topic scope and variety. It was not copied into the game, and its single-question results are not treated as proof of mastery. This first version covers fractions of a whole, conversions, percents, ratios, direct proportions, reverse percents, and inverse relationships.</p></details><section class="journal-section"><h2>Progress over time</h2>${sessions.length?`<p class="subtle">Average skill estimate after each completed journey. Exact per-skill history is below.</p><div class="chart" role="img" aria-label="Average mastery across the last ${sessions.length} journeys">${sessions.map(x=>{const mean=Math.round(Object.values(x.scores).reduce((a,b)=>a+b,0)/Object.keys(SKILLS).length*100);return `<div style="height:${Math.max(4,mean)}%" title="${date(x.at)}: ${mean}%"><span>${mean}%</span></div>`;}).join('')}</div><div class="table-wrap"><table class="history"><thead><tr><th>Date</th><th>Independent / 10</th>${Object.keys(SKILLS).map(k=>`<th>${SKILLS[k]}</th>`).join('')}</tr></thead><tbody>${sessions.slice().reverse().map(x=>`<tr><td>${date(x.at)}</td><td>${x.independent} / 10</td>${Object.keys(SKILLS).map(k=>`<td>${Math.round(x.scores[k]*100)}%</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="empty">The first completed trail will start this history.</div>'}</section><section class="journal-section"><h2>Recent wrong turns</h2>${errors.length?errors.map(x=>`<div class="error-item"><small>${date(x.at)} · ${SKILLS[x.skill]} · Level ${x.level}${x.transfer?' · Transfer challenge':''}${x.assisted?' · Hint used':''}${x.repair?' · Guided retry':''}</small><p>${esc(x.prompt)}</p><span>Chose <strong>${esc(x.chosen)}</strong> · Answer: <strong>${esc(x.answer)}</strong></span></div>`).join(''):'<div class="empty">No errors recorded yet.</div>'}</section><section class="journal-section"><h2>Keep a copy</h2><p class="subtle">Clearing browser data removes local progress. Download a backup to keep or move it to another device.</p><button class="secondary" id="export">Download progress</button> <button class="link" id="import">Restore backup</button><input type="file" id="backupFile" accept="application/json,.json" hidden><p class="subtle" id="backupStatus" role="status"></p></section></section>`;}
function bind(){
 if($('soundToggle'))$('soundToggle').onclick=()=>{soundOn=!soundOn;saveSound();if(soundOn)playSound('toggle');render();};
 if($('begin'))$('begin').onclick=()=>{start(s);save();playSound('start');screen='game';render();};
 if($('pause'))$('pause').onclick=()=>{save();screen='home';render();};
 document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=e=>{if(!s.active?.question||s.active.feedback)return;const event=submit(s,e.currentTarget.dataset.choice);if(!event)return;playSound(event.correct?'correct':'wrong');save();render();$('next')?.focus();});
 if($('hint'))$('hint').onclick=()=>{s.active.question.assisted=true;playSound('hint');save();render();};
 if($('next'))$('next').onclick=()=>{const result=advance(s);if(result!==true){finished=result;screen='finish';playSound('finish');}else playSound('step');save();render();$('question')?.focus();};
 if($('done'))$('done').onclick=()=>{screen='home';finished=null;render();};
 if($('export'))$('export').onclick=()=>{const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify(s,null,2)],{type:'application/json'}));a.href=url;a.download='lantern-hollow-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 if($('import'))$('import').onclick=()=>$('backupFile').click();
 if($('backupFile'))$('backupFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>2000000){$('backupStatus').textContent='That file is too large to be a progress backup.';return;}const restored=restore(await file.text());if(!restored){$('backupStatus').textContent='That file is not a valid Lantern Hollow backup.';return;}if(!confirm('Replace progress in this browser with this backup?'))return;s=restored;finished=null;save();render();$('backupStatus').textContent='Progress restored.';};
}
document.addEventListener('keydown',e=>{if(screen!=='game'||e.repeat||e.ctrlKey||e.metaKey||e.altKey||/INPUT|TEXTAREA/.test(e.target?.tagName))return;if(['1','2','3','4'].includes(e.key)&&!s.active.feedback){document.querySelectorAll('[data-choice]')[Number(e.key)-1]?.click();} });
render();
